import { readFileSync } from "node:fs";

import { expect, expectStatus, sample, test } from "../../fixtures";

test("Documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor } = await factory.vendorInReview();
  expect(vendor.status).toBe("in_review");

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: { kind: "w9", file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) } },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");
  // Re-read: the refused upload must not have been stored.
  const documents = await expectStatus<unknown[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
  expect(documents).toHaveLength(3);
});
